    private void updateStats() {
        int completed = streakManager.getCompletedToday();
        int total = countTasksDueToday() + completed;
        if (statsText != null) {
            statsText.setText(completed + " of " + total + " done today");
        }
        if (streakText != null) {
            int streak = streakManager.getStreak();
            if (streak > 0) {
                streakText.setText("\uD83D\uDD25 " + streak + "-day streak");
                if (rankText != null) {
                    String rank = streakManager.getRankName();
                    int color = streakManager.getRankColor();
                    
                    rankText.setText("Rank: " + rank);
                    rankText.setTextColor(color);
                }
                
                // Infinite Pulse animation on streak card if streak >= 3
                View streakCard = findViewById(R.id.cardView3);
                if (streakCard != null && streak >= 3) {
                    streakCard.startAnimation(android.view.animation.AnimationUtils.loadAnimation(this, R.anim.pulse));
                } else if (streakCard != null) {
                    streakCard.clearAnimation();
                }

                // Small Pulse animation on streak text update
                streakText.animate().scaleX(1.1f).scaleY(1.1f).setDuration(150)
                        .withEndAction(() -> streakText.animate().scaleX(1f).scaleY(1f).setDuration(150).start()).start();
            } else {
                streakText.setText("\uD83D\uDD25 0-day streak");
                if (rankText != null) {
                    rankText.setText("Rank: " + streakManager.getRankName());
                    rankText.setTextColor(streakManager.getRankColor());
                }
                View streakCard = findViewById(R.id.cardView3);
                if (streakCard != null) {
                    streakCard.clearAnimation();
                }
            }
        }
    }

    private void restoreTimerFromService() {
        // If timer service is running but app UI is not showing timer, restore it
        if (TimerService.running && currentTimerTask == null) {
            android.content.SharedPreferences sp = getSharedPreferences("ezpz_active_timer", MODE_PRIVATE);
            String title = sp.getString("task_title", "");
            long timeLeft = sp.getLong("time_left", 0);
            long totalTime = sp.getLong("total_time", 0);
            boolean isPaused = sp.getBoolean("is_paused", false);
            long lastUpdate = sp.getLong("last_update", 0);

            if (title.isEmpty() || timeLeft <= 0) return;

            // Adjust for elapsed time since last save (if running, not paused)
            if (!isPaused && lastUpdate > 0) {
                long elapsed = System.currentTimeMillis() - lastUpdate;
                timeLeft = Math.max(0, timeLeft - elapsed);
            }
            if (timeLeft <= 0) return;

            // Find the matching task
            for (TimelineItem item : allItems) {
                if (title.equals(item.getTitle())) {
                    currentTimerTask = item;
                    break;
                }
            }
            if (currentTimerTask == null) return;

            // Restore UI
            timeLeftMillis = timeLeft;
            totalTimeMillis = totalTime > 0 ? totalTime : timeLeft;
            timerTaskName.setText(title);
            timerTaskName.setVisibility(View.VISIBLE);
            upNextLabel.setVisibility(View.GONE);
            recyclerTimeline.setVisibility(View.GONE);
            aCard.setVisibility(View.GONE);
            inputBar.setVisibility(View.GONE);
            timerContainer.setVisibility(View.VISIBLE);
            timerButtonRow.setVisibility(View.VISIBLE);
            setActionButtonsVisibility(View.GONE);
            findViewById(R.id.filterScrollView).setVisibility(View.GONE);
            if (findViewById(R.id.emptyStateLayout) != null) findViewById(R.id.emptyStateLayout).setVisibility(View.GONE);

            showNextUpPreview();
            updateTimerText();
            updateProgress();

            if (isPaused) {
                timerRunning = false;
                timerText.setAlpha(0.4f);
            } else {
                // Sync with service countdown
                if (countDownTimer != null) countDownTimer.cancel();
                countDownTimer = new CountDownTimer(timeLeftMillis, 1000) {
                    @Override
                    public void onTick(long ms) {
                        timeLeftMillis = ms;
                        updateTimerText();
                        updateProgress();
                    }
                    @Override
                    public void onFinish() {
                        timeLeftMillis = 0;
                        updateTimerText();
                        timerProgress.setProgress(1000);
                        timerRunning = false;
                        onTimerComplete();
                    }
                }.start();
                timerRunning = true;
                timerText.setAlpha(1.0f);
            }
        }
    }

